INSERT INTO playground_problems (id, node_id, difficulty, style, prompt, answer_type, answer, accepted_variants_json, required_form, unit, solution_steps_json, source_doc, content_hash, created_at) VALUES ('L2V-E-04', 'L2V', 'easy', 'word', 'Maria initially has 500 pesos in her savings account. She decides to add 75 pesos to her savings every week. Write a linear equation in slope-intercept form ($y = mx + b$) that represents her total savings ($y$) after $x$ weeks.', 'equation', 'y=75x+500', '[]', 'slope_intercept', NULL, '[{"explanation": "Identify the initial amount, which represents the y-intercept ($b$).", "latex": "b = 500"}, {"explanation": "Identify the constant rate of change (amount added per week), which represents the slope ($m$).", "latex": "m = 75"}, {"explanation": "Substitute these values into the slope-intercept form $y = mx + b$.", "latex": "y = 75x + 500"}]', 'grade8_slope_intercept.pdf', 'sha256:b298f40982df6818a8bfdbe36928a4163db80be20a73e79a54a3e56cb84437fc', '2026-10-28T23:17:34.954040+00:00') ON CONFLICT (id) DO UPDATE SET node_id = EXCLUDED.node_id, difficulty = EXCLUDED.difficulty, style = EXCLUDED.style, prompt = EXCLUDED.prompt, answer_type = EXCLUDED.answer_type, answer = EXCLUDED.answer, accepted_variants_json = EXCLUDED.accepted_variants_json, required_form = EXCLUDED.required_form, unit = EXCLUDED.unit, solution_steps_json = EXCLUDED.solution_steps_json, source_doc = EXCLUDED.source_doc, content_hash = EXCLUDED.content_hash;
